package outbox

import (
	"crypto/rand"
	"database/sql/driver"
	"encoding/binary"
	"encoding/hex"
	"fmt"
	"time"
)

// ID is a message identifier: a 128-bit UUID rendered in the canonical
// 8-4-4-4-12 hexadecimal form.
//
// IDs are generated by [NewID] as UUID version 7 (RFC 9562): a 48-bit
// big-endian Unix millisecond timestamp followed by 74 random bits. They are
// therefore unique, roughly sortable by creation time (which keeps index
// inserts local) and safe to generate concurrently in many processes without
// coordination.
//
// An ID is assigned once, before the enqueueing transaction commits, and never
// changes. Retries of the same message always carry the same ID, which is what
// lets consumers deduplicate.
type ID [16]byte

// NewID returns a new UUIDv7 identifier.
//
// It panics only if the system random source fails, which the standard library
// already treats as unrecoverable.
func NewID() ID {
	var id ID
	ms := uint64(time.Now().UnixMilli())
	id[0] = byte(ms >> 40)
	id[1] = byte(ms >> 32)
	id[2] = byte(ms >> 24)
	id[3] = byte(ms >> 16)
	id[4] = byte(ms >> 8)
	id[5] = byte(ms)
	if _, err := rand.Read(id[6:]); err != nil {
		panic("outbox: crypto/rand failed: " + err.Error())
	}
	id[6] = (id[6] & 0x0f) | 0x70 // version 7
	id[8] = (id[8] & 0x3f) | 0x80 // RFC 9562 variant
	return id
}

// ParseID parses a canonical 36-character UUID string. Applications that want
// deterministic, content-derived identifiers (for example to make enqueueing
// idempotent) can build them elsewhere and parse them here; the only
// requirement is that the value is a UUID.
func ParseID(s string) (ID, error) {
	var id ID
	if len(s) != 36 || s[8] != '-' || s[13] != '-' || s[18] != '-' || s[23] != '-' {
		return id, fmt.Errorf("outbox: invalid message id %q", s)
	}
	for _, g := range [...][3]int{{0, 8, 0}, {9, 13, 4}, {14, 18, 6}, {19, 23, 8}, {24, 36, 10}} {
		if _, err := hex.Decode(id[g[2]:], []byte(s[g[0]:g[1]])); err != nil {
			return ID{}, fmt.Errorf("outbox: invalid message id %q: %w", s, err)
		}
	}
	return id, nil
}

// MustParseID is like [ParseID] but panics on malformed input. It is intended
// for tests and for package-level constants.
func MustParseID(s string) ID {
	id, err := ParseID(s)
	if err != nil {
		panic(err)
	}
	return id
}

// String returns the canonical 36-character representation.
func (id ID) String() string {
	var b [36]byte
	hex.Encode(b[0:8], id[0:4])
	b[8] = '-'
	hex.Encode(b[9:13], id[4:6])
	b[13] = '-'
	hex.Encode(b[14:18], id[6:8])
	b[18] = '-'
	hex.Encode(b[19:23], id[8:10])
	b[23] = '-'
	hex.Encode(b[24:36], id[10:16])
	return string(b[:])
}

// IsZero reports whether the ID is unset.
func (id ID) IsZero() bool { return id == ID{} }

// Time returns the timestamp embedded in a UUIDv7 identifier, truncated to
// milliseconds. It is meaningless for IDs that are not version 7, so callers
// should check the second return value.
func (id ID) Time() (time.Time, bool) {
	if id[6]>>4 != 7 {
		return time.Time{}, false
	}
	var buf [8]byte
	copy(buf[2:], id[0:6])
	ms := binary.BigEndian.Uint64(buf[:])
	return time.UnixMilli(int64(ms)).UTC(), true
}

// MarshalText implements [encoding.TextMarshaler].
func (id ID) MarshalText() ([]byte, error) { return []byte(id.String()), nil }

// UnmarshalText implements [encoding.TextUnmarshaler].
func (id *ID) UnmarshalText(b []byte) error {
	parsed, err := ParseID(string(b))
	if err != nil {
		return err
	}
	*id = parsed
	return nil
}

// Value implements [driver.Valuer] so an ID can be passed straight to a SQL
// driver as a uuid parameter.
func (id ID) Value() (driver.Value, error) { return id.String(), nil }

// Scan implements [sql.Scanner], accepting the text and 16-byte binary forms
// that drivers use for uuid columns.
func (id *ID) Scan(src any) error {
	switch v := src.(type) {
	case nil:
		*id = ID{}
		return nil
	case string:
		return id.UnmarshalText([]byte(v))
	case []byte:
		if len(v) == 16 {
			copy(id[:], v)
			return nil
		}
		return id.UnmarshalText(v)
	case [16]byte:
		*id = v
		return nil
	default:
		return fmt.Errorf("outbox: cannot scan %T into message id", src)
	}
}
